import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("=== STUDENT ONBOARDING SYSTEM ===");

        // 1. String token
        System.out.print("Enter first name: ");
        String firstName = scanner.next();

        // 2. Integer
        System.out.print("Enter roll number: ");
        int rollNo = scanner.nextInt();

        // 3. Double
        System.out.print("Enter 10th grade percentage: ");
        double percentage = scanner.nextDouble();

        // 4. Character via next().charAt(0)
        System.out.print("Enter section (A/B/C): ");
        char section = scanner.next().charAt(0);

        // 5. Boolean
        System.out.print("Hostel resident (true/false): ");
        boolean isHostel = scanner.nextBoolean();

        System.out.println("\n--- CONFIRMED PROFILE ---");
        System.out.printf("Student:    %s (Roll: %d)%n", firstName, rollNo);
        System.out.printf("Section:    %c%n", section);
        System.out.printf("Percentage: %.2f%%%n", percentage);
        System.out.printf("Hosteler:   %s%n", isHostel ? "Yes" : "No");

        scanner.close();
    }
}

